import React, { ChangeEvent, forwardRef } from 'react';

import { _useControllableState } from '../../core/hooks/useControllableState.js';
import type { WithChildren } from '../../core/types/with-children.js';
import type { BaseInputProps } from '../_base-input/BaseInput.js';
import { BaseInput } from '../_base-input/BaseInput.js';
import { BaseInputButton } from '../_base-input/BaseInputButton.js';
import {
  BaseInputSuffix,
  BaseInputPrefix,
} from '../_base-input/BaseInputContent.js';
import type { FormControlRef } from '../shared-types.js';

// #region Typings
export interface TextInputControlledProps {
  /** The default value of the input. */
  defaultValue?: never;
  /** The value of the input. */
  value?: string;
}

export interface TextInputUncontrolledProps {
  /** The default value of the input. */
  defaultValue?: string;
  /** The value of the input. */
  value?: never;
}

export type TextInputProps = Pick<
  BaseInputProps,
  | 'autoComplete'
  | 'name'
  | 'controlState'
  | 'id'
  | 'placeholder'
  | 'disabled'
  | 'required'
  | 'readOnly'
  | 'variant'
  | 'minLength'
  | 'maxLength'
  | 'pattern'
  | 'onKeyDown'
  | 'onKeyUp'
  | 'onFocus'
  | 'onBlur'
  | 'role'
  | 'aria-label'
  | 'aria-labelledby'
  | 'aria-describedby'
  | 'aria-details'
  | 'data-testid'
  | 'className'
  | 'style'
  | 'data-testid'
> &
  WithChildren &
  (TextInputUncontrolledProps | TextInputControlledProps) & {
    /** Handler that is called when the value changes. */
    onChange?: (value: string, event: ChangeEvent<HTMLInputElement>) => void;

    /**
     * Maps to the native input type. Use this to enhance the semantics
     * of the native input, change default keyboards on mobile or support browser
     * autocompletion for specific types.
     * @see https://developer.mozilla.org/en-US/docs/Web/HTML/Element/input#input_types
     *
     * @defaultValue 'text'
     */
    type?: 'text' | 'password' | 'email' | 'url' | 'tel' | 'search';
  };
// #endregion

export const _TextInput = /* @__PURE__ */ forwardRef<
  FormControlRef<HTMLDivElement>,
  TextInputProps
>((props, forwardedRef) => {
  const {
    onChange,
    value,
    defaultValue,
    type = 'text',
    ...remainingProps
  }: TextInputProps = props;

  const noValue = defaultValue === undefined && value === undefined;

  const [internalValue, setInternalValue] = _useControllableState({
    defaultValue: noValue ? '' : defaultValue,
    value,
  });

  const handleOnChange = (e: ChangeEvent<HTMLInputElement>) => {
    onChange?.(e.target.value, e);
    setInternalValue(e.target.value);
  };

  return (
    <BaseInput
      ref={forwardedRef}
      {...remainingProps}
      type={type}
      value={internalValue}
      onChange={handleOnChange}
    />
  );
});

/**
 * Use the `TextInput` component to request a small amount of information,
 * such as a name or an email address. To let users input
 * larger amounts of text, use a `TextArea` instead.
 */
export const TextInput = Object.assign(_TextInput, {
  Prefix: BaseInputPrefix,
  Suffix: BaseInputSuffix,
  Button: BaseInputButton,
});

(TextInput as typeof TextInput & { displayName: string }).displayName =
  'TextInput';
